import resonance.si as si
import resonance.db as db
from resonance.internal import declare_transformation, Processor
import numpy as np
from scipy import signal
import scipy

@declare_transformation
class csp_features(Processor):
    def __init__(self):
        self._si = None
        self._channels = None
        self._window = None
        self._filter = None
        self._prealloc = None

    def prepare(self, input: db.Window, channels=2, normalize=False):
        if not isinstance(input, db.Window):
            raise Exception("input must be window")

        self._window = input.SI.samples

        #self._prealloc = np.zeros((len(), self._window))

        self._si = si.Channels(channels=channels, samplingRate=input.SI.samplingRate)
        return self._si

    def online(self, windows):
        def csp_features(wnd: db.SingleWindow):
            var = np.var(wnd, axis=0)
            var /= np.sum(var)
            return np.log(var)
            
        return db.Channels(self._si, [wnd.timestamps[-1] for wnd in windows], [
            csp_features(wnd) for wnd in windows
        ])
